import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';
import 'package:yaml_edit/yaml_edit.dart';

import '../core/exceptions.dart';

/// Tracks generated files so `--sync` can refresh unchanged outputs safely.
///
/// Stored at `.chico/generate_manifest.yaml`.
final class GenerateManifest {
  GenerateManifest({
    required this.projectRoot,
    Map<String, ManifestEntry>? entries,
  }) : entries = entries ?? {};

  static const relativePath = '.chico/generate_manifest.yaml';

  final String projectRoot;
  final Map<String, ManifestEntry> entries;

  static GenerateManifest load(String projectRoot) {
    final file = File(p.join(projectRoot, relativePath));
    if (!file.existsSync()) {
      return GenerateManifest(projectRoot: projectRoot);
    }
    try {
      final raw = loadYaml(file.readAsStringSync());
      if (raw == null) {
        return GenerateManifest(projectRoot: projectRoot);
      }
      if (raw is! YamlMap) {
        throw const ExecutionException(
          'Generate manifest is corrupt.',
          details: relativePath,
        );
      }
      final files = raw['files'];
      if (files == null) {
        return GenerateManifest(projectRoot: projectRoot);
      }
      if (files is! YamlMap) {
        throw const ExecutionException(
          'Generate manifest is corrupt (files).',
          details: relativePath,
        );
      }
      final entries = <String, ManifestEntry>{};
      for (final entry in files.entries) {
        final path = entry.key.toString().replaceAll('\\', '/');
        final value = entry.value;
        if (value is! YamlMap) {
          throw ExecutionException(
            'Generate manifest entry is corrupt.',
            details: path,
          );
        }
        final hash = value['hash']?.toString() ?? value['sha256']?.toString();
        final generator = value['generator']?.toString() ?? '';
        if (hash == null || hash.isEmpty) {
          throw ExecutionException(
            'Generate manifest entry missing hash.',
            details: path,
          );
        }
        entries[path] = ManifestEntry(generator: generator, hash: hash);
      }
      return GenerateManifest(projectRoot: projectRoot, entries: entries);
    } on DevKitException {
      rethrow;
    } catch (error) {
      throw ExecutionException(
        'Generate manifest is corrupt.',
        details: relativePath,
        cause: error,
      );
    }
  }

  ManifestEntry? operator [](String relativePath) =>
      entries[_normalize(relativePath)];

  void upsert({
    required String relativePath,
    required String generator,
    required String content,
  }) {
    entries[_normalize(relativePath)] = ManifestEntry(
      generator: generator,
      hash: hashContent(content),
    );
  }

  /// True when the on-disk file matches the recorded hash.
  bool isUnchanged(String relativePath) {
    final entry = this[relativePath];
    if (entry == null) return false;
    final file = File(p.join(projectRoot, _normalize(relativePath)));
    if (!file.existsSync()) return false;
    return hashContent(file.readAsStringSync()) == entry.hash;
  }

  Future<void> save() async {
    final editor = YamlEditor('files: {}\n');
    for (final path in entries.keys.toList()..sort()) {
      final entry = entries[path]!;
      editor.update(
        ['files', path],
        {'generator': entry.generator, 'hash': entry.hash},
      );
    }
    final file = File(p.join(projectRoot, relativePath));
    await file.parent.create(recursive: true);
    await file.writeAsString(
      '# Generated by Chico Flutter DevKit — do not edit by hand.\n'
      '${editor.toString()}',
    );
  }

  static String hashContent(String content) {
    // Stable, dependency-light content fingerprint (FNV-1a 64 + length).
    const fnvOffset = 0xcbf29ce484222325;
    const fnvPrime = 0x100000001b3;
    var hash = fnvOffset;
    final units = utf8.encode(content);
    for (final byte in units) {
      hash ^= byte;
      hash = (hash * fnvPrime) & 0xFFFFFFFFFFFFFFFF;
    }
    return '${units.length.toRadixString(16)}-${hash.toRadixString(16)}';
  }

  static String _normalize(String relativePath) =>
      relativePath.replaceAll('\\', '/');
}

final class ManifestEntry {
  const ManifestEntry({required this.generator, required this.hash});

  final String generator;
  final String hash;
}
